examples.basic:
use kiban::db::Kiban;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let mut db = Kiban::open("example-db")?;
    db.put(b"hello", b"world")?;
    db.sync()?; // put alone is not crash-durable
    assert_eq!(db.get(b"hello")?, Some(b"world".to_vec()));
    drop(db);

    let reopened = Kiban::open("example-db")?;
    assert_eq!(reopened.get(b"hello")?, Some(b"world".to_vec()));
    Ok(())
}

examples.batch:
use kiban::db::{Kiban, WriteBatch};

let mut db = Kiban::open(directory)?;
let mut batch = WriteBatch::new();
batch.put(b"hello".to_vec(), b"world".to_vec());
batch.put(b"goodbye".to_vec(), b"moon".to_vec());
batch.delete(b"obsolete".to_vec());
db.write(batch)?;
db.sync()?;
assert_eq!(db.get(b"hello")?, Some(b"world".to_vec()));
assert_eq!(db.get(b"goodbye")?, Some(b"moon".to_vec()));
assert_eq!(db.get(b"obsolete")?, None);

examples.range:
use kiban::db::Kiban;

let mut db = Kiban::open(directory)?;
db.put(b"a", b"1")?;
db.put(b"b", b"2")?;
db.put(b"c", b"3")?;
// Byte-wise ascending order, start included and end excluded.
let entries = db.range(b"a", b"c").collect::<Result<Vec<_>, _>>()?;
assert_eq!(
    entries,
    vec![
        (b"a".to_vec(), b"1".to_vec()),
        (b"b".to_vec(), b"2".to_vec())
    ]
);

examples.shared:
use kiban::db::SharedKiban;

let db = SharedKiban::open(directory)?;
db.put(b"greeting", b"before")?;
let snapshot = db.snapshot()?;
let writer = db.clone();
std::thread::spawn(move || writer.put(b"greeting", b"after"))
    .join()
    .expect("writer panicked")?;
assert_eq!(snapshot.get(b"greeting")?, Some(b"before".to_vec()));
assert_eq!(db.get(b"greeting")?, Some(b"after".to_vec()));
for entry in snapshot.iter() {
    let (key, value) = entry?;
    println!(
        "{} = {}",
        String::from_utf8_lossy(&key),
        String::from_utf8_lossy(&value)
    );
}
drop(snapshot);
db.close()?;

examples.snapshot:
use kiban::db::Kiban;

let mut db = Kiban::open(directory)?;
db.put(b"hello", b"before")?;
let snapshot = db.snapshot();
db.put(b"hello", b"after")?;
assert_eq!(db.get_at(&snapshot, b"hello")?, Some(b"before".to_vec()));
assert_eq!(db.get(b"hello")?, Some(b"after".to_vec()));
